import{_ as l,C as a,o as n,c as s,j as e,a as t,E as o,aj as c}from"./chunks/framework.m090XgxO.js";const k=JSON.parse('{"title":"Layout","description":"","frontmatter":{},"headers":[],"relativePath":"components/layout.md","filePath":"components/layout.md","lastUpdated":1789206102000}'),h={name:"components/layout.md"},u={id:"layout",tabindex:"-1"};function b(p,d,g,x,y,f){const i=a("Badge"),r=a("XhDemo");return n(),s("div",null,[e("h1",u,[d[0]||(d[0]=t("Layout ",-1)),o(i,{type:"info",text:"布局"}),d[1]||(d[1]=t()),d[2]||(d[2]=e("a",{class:"header-anchor",href:"#layout","aria-label":'Permalink to "Layout <Badge type="info" text="布局" />"'},"​",-1))]),d[3]||(d[3]=c('<p>一整页的骨架：头与脚各横贯一行，侧栏与内容并排占中间那一行。少写一段就少一行或少一列。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/layout" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/layout.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/layout" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/layout" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/layout.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>头与脚各横贯一行，侧栏与内容并排占中间那一行；少写一段就少一行或少一列</p>',4)),o(r,{src:"layout/01-basic"}),d[4]||(d[4]=e("h2",{id:"示例",tabindex:"-1"},[t("示例 "),e("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),d[5]||(d[5]=e("h3",{id:"折叠侧栏",tabindex:"-1"},[t("折叠侧栏 "),e("a",{class:"header-anchor",href:"#折叠侧栏","aria-label":'Permalink to "折叠侧栏"'},"​")],-1)),d[6]||(d[6]=e("p",null,"不传 sider-collapsed 即为非受控，把手按下去只改宽度，侧栏节点一直在",-1)),o(r,{src:"layout/02-sider-collapse"}),d[7]||(d[7]=e("h3",{id:"受控",tabindex:"-1"},[t("受控 "),e("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),d[8]||(d[8]=e("p",null,"传了 sider-collapsed 就由宿主说了算，组件不再自改，只发 sider-collapsed-change",-1)),o(r,{src:"layout/03-controlled"}),d[9]||(d[9]=e("h3",{id:"侧栏位置",tabindex:"-1"},[t("侧栏位置 "),e("a",{class:"header-anchor",href:"#侧栏位置","aria-label":'Permalink to "侧栏位置"'},"​")],-1)),d[10]||(d[10]=e("p",null,"sider-placement 决定侧栏挂在行首还是行尾，分隔线也跟着换到挨内容的那一边",-1)),o(r,{src:"layout/04-sider-placement"}),d[11]||(d[11]=e("h3",{id:"侧栏宽度",tabindex:"-1"},[t("侧栏宽度 "),e("a",{class:"header-anchor",href:"#侧栏宽度","aria-label":'Permalink to "侧栏宽度"'},"​")],-1)),d[12]||(d[12]=e("p",null,"展开与折叠各一档宽度，两档都接受任意 CSS 长度，切换时按皮肤里的过渡走",-1)),o(r,{src:"layout/05-sider-width"}),d[13]||(d[13]=e("h3",{id:"吸顶与固定",tabindex:"-1"},[t("吸顶与固定 "),e("a",{class:"header-anchor",href:"#吸顶与固定","aria-label":'Permalink to "吸顶与固定"'},"​")],-1)),d[14]||(d[14]=e("p",null,"header-fixed 让头钉在滚动容器上沿，sider-fixed 让侧栏跟着钉住；两个一起用时侧栏自动让开头的高度",-1)),o(r,{src:"layout/06-fixed"}),d[15]||(d[15]=e("h3",{id:"分别固定",tabindex:"-1"},[t("分别固定 "),e("a",{class:"header-anchor",href:"#分别固定","aria-label":'Permalink to "分别固定"'},"​")],-1)),d[16]||(d[16]=e("p",null,"两个开关各自独立：只写 header-fixed 时侧栏照常随内容滚走，只写 sider-fixed 时侧栏钉在滚动容器上沿、头照常滚走",-1)),o(r,{src:"layout/07-fixed-independent"}),d[17]||(d[17]=e("h3",{id:"侧栏覆盖档",tabindex:"-1"},[t("侧栏覆盖档 "),e("a",{class:"header-anchor",href:"#侧栏覆盖档","aria-label":'Permalink to "侧栏覆盖档"'},"​")],-1)),d[18]||(d[18]=e("p",null,'sider-presentation="sheet" 把侧栏移出画外，唤出来时盖在内容之上；点遮罩或按 Escape 收起',-1)),o(r,{src:"layout/08-sider-sheet"}),d[19]||(d[19]=c('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>搭一个应用外壳：管理后台、控制台、文档站。</li><li>侧栏需要折叠，且折叠时节点仍在（只改宽度，不卸载）。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>只是把几个块并排：用<a href="./flex">弹性布局</a>或<a href="./grid">栅格</a>。</li><li>两块区域之间要由用户拖动分配空间：用<a href="./splitter">分栏</a>。</li><li>侧栏本身是一棵可展开的导航树：布局只出壳，树交给<a href="./side-nav">侧栏导航</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>七个部件都可选，只写用得上的那几段。</li><li>折叠只改宽度，侧栏节点一直在：里面的滚动位置与焦点不会丢。</li><li>展开与折叠各一档宽度，两档都接受任意 CSS 长度。</li><li><code>headerFixed</code> 与 <code>siderFixed</code> 各自独立；两个一起用时侧栏自动让开头的高度。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-layout&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhLayoutContent</code> <code>XhLayoutFooter</code> <code>XhLayoutHeader</code> <code>XhLayoutRoot</code> <code>XhLayoutSider</code> <code>XhLayoutSiderBackdrop</code> <code>XhLayoutSiderTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useLayout</code></td></tr><tr><td>状态机</td><td><code>layoutMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/layout.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;layout&quot;</code>：<strong><code>root</code></strong> · <code>header</code> · <code>sider-backdrop</code> · <code>sider</code> · <code>content</code> · <code>footer</code> · <code>sider-trigger</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>siderCollapsed</code></td><td><code>boolean</code></td><td></td><td>受控折叠态：给了值就由宿主说了算。</td></tr><tr><td><code>defaultSiderCollapsed</code></td><td><code>boolean</code></td><td></td><td>非受控初始折叠态。</td></tr><tr><td><code>siderWidth</code></td><td><code>string</code></td><td></td><td>展开时侧栏的宽度，任意 CSS 长度；不写则用皮肤里的档位。</td></tr><tr><td><code>siderCollapsedWidth</code></td><td><code>string</code></td><td></td><td>折叠时侧栏的宽度，任意 CSS 长度；不写则用皮肤里的档位。</td></tr><tr><td><code>siderPlacement</code></td><td><code>LayoutSiderPlacement</code></td><td></td><td>侧栏挂在行首还是行尾，缺省 start。</td></tr><tr><td><code>siderBreakpoint</code></td><td><code>LayoutBreakpoint</code></td><td></td><td>侧栏的自适应断点：视口窄于这一档时侧栏按折叠宽显示。 只换宽度不改折叠态——折叠态归 siderCollapsed 那条通道，两者互不干扰。 运行期换档会重绑媒体查询；需要所属 Window.matchMedia 与对应断点令牌。</td></tr><tr><td><code>siderPresentation</code></td><td><code>LayoutSiderPresentation</code></td><td></td><td>侧栏呈现形态，缺省 inline（在骨架里占一列）。 sheet 是覆盖档：侧栏移出画外，展开时盖在内容之上并铺一层遮罩，内容因此占满整宽。 同时写了 siderBreakpoint 时它只在未达那一档时成立——宽屏照旧占一列，窄屏才覆盖， 且跨档时侧栏跟着开合（进覆盖档收起、回占位档展开），走的是 siderCollapsed 那条通道。 覆盖档不锁焦点、不把背后的内容标成惰性：它是骨架里的一段，不是模态浮层。</td></tr><tr><td><code>headerFixed</code></td><td><code>boolean</code></td><td></td><td>头吸顶：滚动时头钉在滚动容器的上沿。只落标记，钉住的实现归皮肤。</td></tr><tr><td><code>siderFixed</code></td><td><code>boolean</code></td><td></td><td>侧栏吸附：滚动时侧栏钉在滚动容器的上沿，头也吸顶时让开头那一条。只落标记，钉住的实现归皮肤。</td></tr><tr><td><code>bordered</code></td><td><code>boolean</code></td><td></td><td>在头、侧栏、脚与内容之间画分隔线。</td></tr><tr><td><code>onSiderCollapsedChange</code></td><td><code>(details: LayoutSiderCollapsedChangeDetails) =&gt; void</code></td><td></td><td>折叠态变化意图回调；受控时是唯一出口，非受控随内部转移一并通知。</td></tr><tr><td><code>onSiderBreakpoint</code></td><td><code>(details: LayoutSiderBreakpointDetails) =&gt; void</code></td><td></td><td>断点跨过去时发一次，挂载或更换档位时也发一次当前值。 窄屏要把侧栏换成抽屉的，接这条：组件自己只换宽度。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>sider-collapsed-change</code></td><td><code>LayoutSiderCollapsedChangeDetails</code></td><td>折叠态变化；detail 为 <code>{ collapsed: boolean }</code></td></tr><tr><td><code>sider-breakpoint</code></td><td><code>LayoutSiderBreakpointDetails</code></td><td>断点跨过去时发，挂载时也发一次当前值；detail 为 <code>{ matched: boolean }</code></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>expanded</code> · <code>collapsed</code></p><p><strong>事件</strong>：<code>SIDER.COLLAPSE</code> · <code>SIDER.EXPAND</code> · <code>SIDER.TOGGLE</code> · <code>CONTROLLED.COLLAPSE</code> · <code>CONTROLLED.EXPAND</code></p><p><strong>判据</strong>：<code>isSiderCollapsedControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useLayout</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>siderCollapsed</code></td><td><code>boolean</code></td><td>侧栏当前是否折叠。</td></tr><tr><td><code>siderPresentation</code></td><td><code>LayoutSiderPresentation</code></td><td>已解析的侧栏呈现形态：写了断点时，覆盖档只在未达那一档时成立。</td></tr><tr><td><code>setSiderCollapsed</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSiderBackdropProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>覆盖档铺在内容之上的那一层遮罩：点它收起侧栏。 占位档下它带 hidden，不占位也不吃指针。渲染时排在侧栏之前——两层同一个层号，谁盖谁看文档序。</td></tr><tr><td><code>getSiderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getFooterProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSiderTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/disclosure/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Space</code> / <code>Enter</code></td><td>focus in sider-trigger</td><td>折叠/展开 sider</td></tr><tr><td><code>Escape</code></td><td>sider 按覆盖档盖在内容之上</td><td>收起 sider</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>sider-backdrop</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>sider-trigger</code></td><td><code>aria-controls</code></td><td><code>sider</code> 部件的 id</td></tr><tr><td><code>sider-trigger</code></td><td><code>aria-expanded</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/layout.css</code> 按部件选择：<code>[data-scope=&quot;layout&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-bordered</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-collapsed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-header-fixed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-sider-breakpoint</code></td><td>props.siderBreakpoint</td></tr><tr><td><code>root</code></td><td><code>data-sider-fixed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-sider-placement</code></td><td>props.siderPlacement</td></tr><tr><td><code>root</code></td><td><code>data-sider-presentation</code></td><td>resolveSiderPresentation( prop(&#39;siderPresentation&#39;), …</td></tr><tr><td><code>header</code></td><td><code>data-fixed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>sider-backdrop</code></td><td><code>data-collapsed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>sider</code></td><td><code>data-collapsed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>sider</code></td><td><code>data-fixed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>sider</code></td><td><code>data-placement</code></td><td>props.siderPlacement</td></tr><tr><td><code>sider</code></td><td><code>data-presentation</code></td><td>resolveSiderPresentation( prop(&#39;siderPresentation&#39;), …</td></tr><tr><td><code>sider-trigger</code></td><td><code>data-collapsed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-layout-bg</code></td><td><code>root</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-page</code></td><td>layout 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-layout-border</code></td><td><code>footer</code><br><code>header</code><br><code>root</code><br><code>sider</code></td><td><code>border-block-end</code><br><code>border-block-start</code><br><code>border-inline-end</code><br><code>border-inline-start</code></td><td><code>bordered</code><br><code>placement=end</code><br><code>placement=start</code></td><td><code>--xh-border-default</code></td><td>layout 的 footer、header、root、sider 部件 border-block-end、border-block-start、border-inline-end、border-inline-start 覆盖槽。</td></tr><tr><td><code>--xh-layout-content-padding</code></td><td><code>content</code></td><td><code>padding</code></td><td><code>default</code></td><td><code>--xh-space-4</code></td><td>layout 的 content 部件 padding 覆盖槽。</td></tr><tr><td><code>--xh-layout-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>layout 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-layout-footer-bg</code></td><td><code>footer</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-surface</code></td><td>layout 的 footer 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-layout-footer-padding</code></td><td><code>footer</code></td><td><code>padding</code></td><td><code>default</code></td><td><code>--xh-space-3</code></td><td>layout 的 footer 部件 padding 覆盖槽。</td></tr><tr><td><code>--xh-layout-header-bg</code></td><td><code>header</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-surface</code></td><td>layout 的 header 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-layout-header-gap</code></td><td><code>header</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-3</code></td><td>layout 的 header 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-layout-header-h</code></td><td><code>header</code><br><code>root</code><br><code>sider</code></td><td><code>block-size</code><br><code>grid-template-rows</code><br><code>inset-block-start</code><br><code>max-block-size</code></td><td><code>default</code><br><code>fixed</code><br><code>header-fixed</code><br><code>sider-fixed</code></td><td><code>3.5rem</code></td><td>layout 的 header、root、sider 部件 block-size、grid-template-rows、inset-block-start、max-block-size 覆盖槽。</td></tr><tr><td><code>--xh-layout-header-layer</code></td><td><code>header</code></td><td><code>z-index</code></td><td><code>fixed</code></td><td><code>--xh-layer-sticky</code></td><td>layout 的 header 部件 z-index 覆盖槽。</td></tr><tr><td><code>--xh-layout-header-px</code></td><td><code>header</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-space-4</code></td><td>layout 的 header 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-layout-scrollport-h</code></td><td><code>sider</code></td><td><code>max-block-size</code></td><td><code>fixed</code><br><code>presentation=sheet</code></td><td><code>100dvh</code><br><code>100vh</code></td><td>layout 的 sider 部件 max-block-size 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-backdrop-bg</code></td><td><code>sider-backdrop</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-overlay</code></td><td>layout 的 sider-backdrop 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-backdrop-layer</code></td><td><code>sider-backdrop</code></td><td><code>z-index</code></td><td><code>default</code></td><td><code>--xh-layer-drawer</code></td><td>layout 的 sider-backdrop 部件 z-index 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-bg</code></td><td><code>sider</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-subtle</code></td><td>layout 的 sider 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-collapsed-w</code></td><td><code>root</code><br><code>sider</code></td><td><code>inline-size</code></td><td><code>collapsed</code><br><code>sider-breakpoint</code></td><td><code>4rem</code></td><td>layout 的 root、sider 部件 inline-size 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-layer</code></td><td><code>sider</code></td><td><code>z-index</code></td><td><code>presentation=sheet</code></td><td><code>--xh-layer-drawer</code></td><td>layout 的 sider 部件 z-index 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-padding</code></td><td><code>sider</code></td><td><code>padding</code><br><code>padding-block-end</code><br><code>padding-block-start</code><br><code>padding-inline</code></td><td><code>default</code><br><code>presentation=sheet</code></td><td><code>--xh-space-3</code></td><td>layout 的 sider 部件 padding、padding-block-end、padding-block-start、padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-shadow</code></td><td><code>sider</code></td><td><code>box-shadow</code></td><td><code>presentation=sheet</code></td><td><code>--xh-elevation-sheet</code></td><td>layout 的 sider 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-trigger-bg</code></td><td><code>sider-trigger</code></td><td><code>background</code></td><td><code>default</code></td><td><code>transparent</code></td><td>layout 的 sider-trigger 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-trigger-bg-active</code></td><td><code>sider-trigger</code></td><td><code>background</code></td><td><code>active</code></td><td><code>--xh-bg-subtle-active</code></td><td>layout 的 sider-trigger 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-trigger-bg-hover</code></td><td><code>sider-trigger</code></td><td><code>background</code></td><td><code>hover</code></td><td><code>--xh-bg-subtle-hover</code></td><td>layout 的 sider-trigger 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-trigger-fg</code></td><td><code>sider-trigger</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>layout 的 sider-trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-trigger-gap</code></td><td><code>sider-trigger</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-control-gap-sm</code></td><td>layout 的 sider-trigger 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-trigger-px</code></td><td><code>sider-trigger</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-control-px-sm</code></td><td>layout 的 sider-trigger 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-trigger-radius</code></td><td><code>sider-trigger</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>layout 的 sider-trigger 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-layout-sider-w</code></td><td><code>root</code><br><code>sider</code></td><td><code>inline-size</code></td><td><code>@media (min-width: 1024px)</code><br><code>@media (min-width: 1280px)</code><br><code>@media (min-width: 640px)</code><br><code>@media (min-width: 768px)</code><br><code>default</code><br><code>presentation=sheet</code><br><code>sider-breakpoint=lg</code><br><code>sider-breakpoint=md</code><br><code>sider-breakpoint=sm</code><br><code>sider-breakpoint=xl</code></td><td><code>15rem</code></td><td>layout 的 root、sider 部件 inline-size 覆盖槽。</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p><code>background</code> · <code>inline-size</code> · <code>opacity</code> · <code>scale</code> · <code>translate</code> · <code>visibility</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h2><p>皮肤按视口分档：<code>min-width: 1024px</code> · <code>min-width: 1280px</code> · <code>min-width: 640px</code> · <code>min-width: 768px</code>。</p><ul><li><code>siderBreakpoint</code> 给一档（<code>sm</code> / <code>md</code> / <code>lg</code> / <code>xl</code>），视口窄于这一档时侧栏按折叠宽显示。 它只换宽度、不改折叠态：折叠态归 <code>siderCollapsed</code> 那条通道，两者互不干扰。</li><li>断点跨过去时发 <code>onSiderBreakpoint</code>，挂载时也发一次当前值。要在窄屏改换别的排布，接这个回调。</li><li>运行期修改 <code>siderBreakpoint</code> 会立即切换媒体查询、报告新档位当前值；移除该属性会解除观察并清除窄屏标记，保留当前折叠态。 <code>siderPresentation</code> 切到 <code>sheet</code> 时立即应用当前断点，受控折叠态仍由宿主写回。 断点令牌在属性更新和媒体查询事件时重新读取，单独修改 CSSOM 不会主动触发重绑。 已指定断点却缺少令牌或所属 Window 的 <code>matchMedia</code> 会明确报错；同步失败会解除监听，不再沿用旧档位，需以有效属性更新重新建立。</li><li><code>siderPresentation=&quot;sheet&quot;</code> 是覆盖档：侧栏移出画外，展开时盖在内容之上并铺一层遮罩，内容占满整宽。 与 <code>siderBreakpoint</code> 配着写就是「宽屏占一列、窄屏覆盖」——跨档时侧栏跟着开合， 进覆盖档收起、回占位档展开，走的仍是 <code>siderCollapsed</code> 那条通道。</li><li>覆盖档下点遮罩或按 Escape 收起侧栏，<code>sider-trigger</code> 照旧是把它唤出来的那个控件。</li><li>覆盖侧栏通过共享 Document Hub 的空栈 fallback 接收 Escape，并读取当前组件的 <code>RuntimeConfig.layerRegistry</code>。capture 时只要该栈存在对话框、菜单等 Layer，本键就归上层消费； 即使 Layer 同步退栈，仍要到下一次 Escape 才收侧栏。自定义 LayerRegistry 与同一 Document 的默认注册表互不干扰。</li><li>同一 LayerRegistry 下同时展开多个覆盖侧栏时，每次 Escape 只收最近展开的一个；受控侧栏未写回 折叠态时持续占住这个位置。占位档与当前断点解析为 inline 的侧栏会被动态跳过。</li><li>直接使用 headless 机器时，要在 mount 前把与机器 Scope 属于同一 Document 的 <code>RuntimeConfig</code> 写进 <code>LayoutRefs.config</code>；缺失或跨 Document 混接都会明确失败。Vue、React 与 Web Components 适配器已经完成这段接线。</li><li>覆盖档不锁焦点、不把背后的内容标成惰性：它是骨架里的一段，不是模态浮层。要模态用<a href="./drawer">抽屉</a>。</li><li>遮罩渲染在侧栏之前：两层同一个层号，谁盖谁由文档序决定。</li><li>覆盖档下侧栏贴死视口，内衬与安全区取大的一头，所以 <code>--xh-layout-sider-padding</code> 在这一档要写单值（<code>max()</code> 收不了简写的多值）。</li></ul><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li><code>sider</code> 里放<a href="./side-nav">侧栏导航</a>，<code>header</code> 里放<a href="./menubar">菜单栏</a>或<a href="./toolbar">工具栏</a>，<code>content</code> 里放<a href="./page-header">页头</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>内容区自己定高、内部滚动，别让整页滚动——吸顶的头与侧栏才立得住。</li><li>折叠态的宽度要放得下图标加内边距，否则图标会被裁。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>折叠时把侧栏整个卸载再挂回来：展开的分支、滚动位置、焦点全部重置。</li><li>头和侧栏都不吸附却给它们设了 <code>position: fixed</code>：占位没了，内容会被盖住。</li></ul>',53))])}const P=l(h,[["render",b]]);export{k as __pageData,P as default};
